action.command:
cd /workspace
# Verify container state is intact
docker ps --format "{{.Names}}\t{{.Status}}" | grep -c "Up"; echo "containers up"
# Check current dev-server state
cat .urbo/workspace/ports.json 2>/dev/null
# Confirm no stale dev servers listening on those ports
node -e '
const {createConnection}=require("node:net");
for (const p of [37315]) {
  const s=createConnection({port:p,host:"127.0.0.1",timeout:500});
  s.on("connect",()=>{console.log(p,"OPEN (stale server)");s.destroy();});
  s.on("error",()=>console.log(p,"closed"));
  s.on("timeout",()=>{console.log(p,"timeout");s.destroy();});
}'

